    "description": "南京海事局11月25日公布《南京“5·6”“H”轮与“S”轮碰撞事故调查报告》。2026年5月6日1853时许，巴拿马籍“H”轮（载煤炭26610吨驶往南京）在长江#137浮附近水域由北向南横越时，与沿下行通航分道下行的“S”轮（自安徽巢湖载运水泥熟料1243.88吨驶往浙江湖州）发生碰撞。事故导致“S”轮沉没、货物灭失、2人死亡；“H”轮艏尖舱局部破损进水，未造成水域污染，构成一般等级水上交通事故。 经调查，本起事故是一起横越船与顺航…",
    "content": "南京海事局11月25日公布《南京“5·6”“H”轮与“S”轮碰撞事故调查报告》。2026年5月6日1853时许，巴拿马籍“H”轮（载煤炭26610吨驶往南京）在长江#137浮附近水域由北向南横越时，与沿下行通航分道下行的“S”轮（自安徽巢湖载运水泥熟料1243.88吨驶往浙江湖州）发生碰撞。事故导致“S”轮沉没、货物灭失、2人死亡；“H”轮艏尖舱局部破损进水，未造成水域污染，构成一般等级水上交通事故。 经调查，本起事故是一起横越船与顺航道行驶船舶之间发生的碰撞责任事故。“H”轮横越时未主动避让顺航道行驶船舶、紧急避…"
