    "title": "印尼西爪哇矿井事故遇难人数升至9人",
    "link": "http://www.news.cn/20261125/b180cec7a42c4425b823324aafc20ab2/c.html",
    "pub_date": "2026-11-25 22:45:10",
    "author": "",
    "description": "新华社雅加达11月25日电（记者张怡晟）据印度尼西亚搜救部门25日消息，搜救人员在该国西爪哇省茂物县一处矿井内累计发现9名矿工的遗体，目前仍在全力搜救据报被困井下的17名矿工。 当地搜救部门表示，出事矿井深约100米。事发时，有11名矿工成功逃生。目前，抽水排险和搜救工作仍在紧张进行，井下积水、通道狭窄、照明不足及湿滑地形等因素，给救援带来较大困难。 印尼搜救部门此前通报说，事故发生于23日下午，当时该地区正下大雨，河水泛滥倒灌进矿井。…",
    "content": "新华社雅加达11月25日电（记者张怡晟）据印度尼西亚搜救部门25日消息，搜救人员在该国西爪哇省茂物县一处矿井内累计发现9名矿工的遗体，目前仍在全力搜救据报被困井下的17名矿工。 当地搜救部门表示，出事矿井深约100米。事发时，有11名矿工成功逃生。目前，抽水排险和搜救工作仍在紧张进行，井下积水、通道狭窄、照明不足及湿滑地形等因素，给救援带来较大困难。 印尼搜救部门此前通报说，事故发生于23日下午，当时该地区正下大雨，河水泛滥倒灌进矿井。由于涉及非法采矿，事发后相关人员并未第一时间报警。直至25日凌晨，搜救部门才接到…"
