    "content": "新华社瑞士伯尔尼11月25日电（记者焦倩）“中瑞创新战略伙伴关系10周年”研讨会24日在瑞士伯尔尼举行。来自中瑞两国政府、企业及创新领域约200名代表齐聚一堂，回顾两国创新合作成果，探讨进一步拓展经贸、科研和创新合作机遇。 瑞士联邦主席帕姆兰在致辞中表示，瑞中创新战略伙伴关系建立10年来，双方有充分理由对未来合作充满信心。他说，瑞中自贸协定升级议定书的签署是一个重要里程碑，双方需要进一步采取行动，推动升级版协定落地生效。他呼吁企业界和专业人士积极参与，将共同愿景转化为务实合作。 中国驻瑞士大使钱敏坚说，中方愿同瑞方…"
