    "content": "兴业证券首席策略分析师张启尧离职，下一站是国联民生证券。 11月25日，兴业证券（601377.SH）经济与金融研究院对澎湃新闻记者确认，张启尧已离职。同时，澎湃新闻记者从张启尧本人处了解到，他将加盟国联民生（601456.SH、01456.HK），担任研究所副所长兼首席策略官。 公开资料显示，张启尧早年即在兴业证券从事策略研究，2018年曾短暂加盟国盛证券，并于2021年重返老东家。 兴证策略团队此前发布的成员介绍显示，张启尧拥有悉尼大学金融学硕士学位，2014年加入兴业证券研究所，先后担任策略分析师、高级策略分…"
