    "content": "伊朗中国和平统一促进会成立仪式日前在伊朗首都德黑兰举行。 中国驻伊朗大使丛培武在成立仪式上致辞表示，解决台湾问题、实现祖国完全统一，是中国共产党矢志不渝的历史任务，是全体中华儿女的共同愿望，是实现中华民族伟大复兴的必然要求。希望各位侨领牢记初心使命，团结带领在伊侨胞，坚定站在历史正确一边，积极作为、笃行实干，把伊朗中国和平统一促进会建设好、发展好。 伊朗中国和平统一促进会首任会长马正华表示，旅伊侨胞虽身在海外，但始终心系华夏。未来，伊朗中国和平统一促进会将坚定奉行一个中国原则，坚决反对任何形式的“台独”分裂行径，广…"
