    "content": "新华社日内瓦11月25日电 中国与巴西24日在世界贸易组织联合举办新兴农业贸易问题对话会，围绕小农户与合作社如何融入全球农产品价值链展开讨论。 本次对话会以“农民、合作社与贸易：连接生产者、市场与粮食安全”为主题。中国常驻世贸组织副代表胡盈之与巴西常驻世贸组织副代表埃丽卡·帕特里奥塔在开幕致辞中指出，小农户是发展中国家农业生产的中坚力量，但在参与市场特别是国际贸易时普遍面临信息不对称、议价能力弱及合规成本高等困难。世贸组织应切实服务广大中小农业生产者，充分发挥合作社桥梁作用，有效降低交易成本，促进贸易利益共享，更好…"
