    "description": "新华社北京11月25日电（记者阳娜）记者25日从北京市减轻企业负担联席会议办公室获悉，北京深化支持小微企业融资协调工作机制，开展“千企万户大走访”活动，深入摸排小微企业融资需求，大力推动银企对接，截至今年9月底，已走访小微经营主体240余万户，帮助企业获得贷款超9700亿元，切实解决小微企业融资难题。 北京持续执行减税降费政策，支持企业稳岗扩岗，强化金融支持实体经济，比如在地方权限范围内顶格确定北京市税费政策执行标准，如顶格制定创业就业…",
    "content": "新华社北京11月25日电（记者阳娜）记者25日从北京市减轻企业负担联席会议办公室获悉，北京深化支持小微企业融资协调工作机制，开展“千企万户大走访”活动，深入摸排小微企业融资需求，大力推动银企对接，截至今年9月底，已走访小微经营主体240余万户，帮助企业获得贷款超9700亿元，切实解决小微企业融资难题。 北京持续执行减税降费政策，支持企业稳岗扩岗，强化金融支持实体经济，比如在地方权限范围内顶格确定北京市税费政策执行标准，如顶格制定创业就业税收政策，顶格减征“六税两费”、文化事业建设费等；实施扩大社保补贴范围政策，持续…"
