    "content": "新华社香港11月25日电（张雅诗）香港理工大学（理大）25日在该校校园举行“2026福建文化周”开幕式。活动通过主题展览、沉浸体验市集、学术交流座谈及体验课堂等，多角度呈现福建文化与香港的深厚渊源。 2026福建文化周以“丝路潮起·闽港同心”为主题，是今年理大中华文化节的压轴活动，亮点包括“八闽文脉全景主题展”，呈现福建的海上丝绸之路文明、世界文化遗产价值、非物质文化遗产技艺、闽式生活和闽港侨缘。 理大校董会主席林大辉在开幕式上致辞表示，理大重视弘扬中华文化及推动爱国主义教育，每年举办中华文化节，以提升学生对国家的…"
