    "description": "电视节目里，远离家乡的儿子接过主持人手里的餐盘，边说笑边拿起筷子，夹起一个饺子放进嘴里。他的表情逐渐凝重，眼里慢慢浸出泪花。他轻声问主持人：“我妈来现场了？”主持人笑着反问：“为什么这么问？”他哽咽：“这是我妈妈的味道。我已经三年没回家，没吃到我妈包的饺子了。” 话音刚落，妈妈走上台，母子二人紧紧拥抱在一起。这段视频看得我热泪盈眶。 我拍拍儿子感慨道：“每次看这样的视频，我都会深刻反思。” 儿子疑惑：“反思什么？”我叹气：“如果节目里这…",
    "content": "电视节目里，远离家乡的儿子接过主持人手里的餐盘，边说笑边拿起筷子，夹起一个饺子放进嘴里。他的表情逐渐凝重，眼里慢慢浸出泪花。他轻声问主持人：“我妈来现场了？”主持人笑着反问：“为什么这么问？”他哽咽：“这是我妈妈的味道。我已经三年没回家，没吃到我妈包的饺子了。” 话音刚落，妈妈走上台，母子二人紧紧拥抱在一起。这段视频看得我热泪盈眶。 我拍拍儿子感慨道：“每次看这样的视频，我都会深刻反思。” 儿子疑惑：“反思什么？”我叹气：“如果节目里这个妈妈换成我，你能吃出妈妈的味道吗？”儿子忍不住“嗤嗤”一笑，我重重叹了口气。 …"
