    "content": "武强年画起于宋元，兴于明清，作为国家级非物质文化遗产，扎根乡土、薪火绵延。 依托全国首家年画博物馆，河北省衡水市武强县深耕古版保护考据，传承人守古法、拓新路，让古老年画跨越时空，在当代焕发新生。 &nbsp; 作者：邹尚伯、张凯、张松 新华社音视频部制作"
