    "content": "新华社北京11月25日电 伊朗第一副总统穆罕默德·礼萨·阿雷夫25日说，伊朗不惧怕美国海上封锁，伊朗政府正采取措施遏制物价上涨。 路透社援引阿雷夫的话报道，除沿波斯湾的南部边境外，伊朗其他边境口岸的货物卸载和清关量显著增加，表明伊朗“不惧敌方海上封锁”。他表示，伊朗目前战略物资储备充足，供应丰富。但他未提及具体数据。 阿雷夫还表示，政府计划在至少三个月内确保基本生活物资价格稳定。伊朗统计中心数据显示，该国10月消费价格同比上涨88.7%，年均通胀率升至76.8%，其中食品和饮料价格同比上涨112.6%。 2025年…"
