    "content": "中共政治局委员、上海市委书记陈吉宁被查，上海市人大常委会党组、市政府党组、市政协党组分别召开会议通报情况，均表态坚决拥护中共中央决定，并称陈吉宁被查充分表明中共有腐必反、有贪必肃的鲜明态度，强调要更加自觉把加强党性修养作为终身课题。 据澎湃新闻报道，上海市委副书记、市长、市政府党组书记朱忠明星期三（11月25日）主持召开市政府党组会议时指出，中央纪委国家监委对陈吉宁涉嫌严重违纪违法进行审查调查，充分体现了中共中央持之以恒推进全面从严治党、把党的自我革命进行到底的坚强意志和坚定决心，也充分释放了反腐败斗争无禁区、全覆…"
