    "content": "11月25日，神舟二十四号载人飞船入轨后，成功对接于空间站天和核心舱。中国“天宫”迎来首位外籍航天员——来自巴基斯坦的穆罕默德·齐尚·阿里。 素馨花是巴基斯坦的国花，它也出现在神舟二十四号载人飞行任务标识中。 记者：张敬尧、杨恺、李俞辉 报道员：艾哈迈德 新华社音视频部制作"
