    "content": "新华社广州11月25日电（记者马晓澄、周颖）记者在25日举办的第五届琶洲算法大赛生态赋能大会上获悉，在广州举办的该赛事吸引来自87个国家和地区的10263支队伍报名参加，已成为链接全球人工智能创新资源与大湾区产业需求的重要平台。 这是11月25日拍摄的2026琶洲算法大赛生态赋能大会现场。新华社记者 卢汉欣 摄 本届大赛于今年2月拉开帷幕，经历数月角逐，于11月25日公布赛果。大赛设置25道赛题，覆盖AI大模型算法优选赛、AI创新应用赛、前沿技术挑战赛、国际AI赛以及生态合作赛等五大赛道，涉及大模型、智能硬件、生命…"
