    "content": "新华社莫斯科11月25日电 第七届中俄媒体论坛25日在莫斯科举行。与会嘉宾表示，在两国元首战略引领下，中俄媒体合作不断拓展，成果丰硕，要以本届论坛为契机，共同开创数智时代中俄媒体合作新局面。 与会嘉宾指出，今年以来，中俄元首多次举行会晤，就扩大人文交流达成共识，共同见证签署多项媒体合作协议。会晤成果明确提出共同办好中俄媒体论坛、促进主流媒体互访、加强人才联合培养，为中俄媒体深化合作提供重要指引。 与会嘉宾认为，当前数智技术正重塑内容生产与传播格局，两国媒体应把探索与实践相结合，在内容共创、技术协作、人才培养等方面深…"
