    "content": "新华社重庆11月25日电 重庆市纪委监委25日通报，经重庆市委批准，重庆市纪委监委对重庆市文化旅游委原党委委员、副主任朱茂严重违纪违法问题进行了立案审查调查。 经查，朱茂丧失理想信念，背弃初心使命，搞投机钻营，结交政治骗子，对抗组织审查；无视中央八项规定精神，违规收受礼金；违反组织原则，不按规定报告个人有关事项；廉洁底线失守，通过民间借贷获取大额回报，违规从事营利活动；违规干预和插手工程项目承发包，违规为私企贷款提供担保；私欲膨胀，利用职务便利为他人在工程承揽、规划调整等方面谋利，并非法收受巨额财物。 朱茂严重违反…"
