    "description": "36氪获悉，蔚来正式发布面向整车原生设计的NOMI Intelligence 4.0，将分阶段覆盖各大蔚来智能系统，搭载NOMI 4.0的第一个版本 “Cedar雪松2.0.0”，将于12月初提交备案，通过后陆续开始推送；“Cedar S雪松”和“Banyan榕”智能系统，预计在2027年第二季度完成适配并推送。",
    "content": "36氪获悉，蔚来正式发布面向整车原生设计的NOMI Intelligence 4.0，将分阶段覆盖各大蔚来智能系统，搭载NOMI 4.0的第一个版本 “Cedar雪松2.0.0”，将于12月初提交备案，通过后陆续开始推送；“Cedar S雪松”和“Banyan榕”智能系统，预计在2027年第二季度完成适配并推送。"
