    "title": "瞰中国丨湖南冷水滩：梧桐披金美如画",
    "link": "http://www.news.cn/20261125/25706ad9e856494ea9a30351085cc8f3/c.html",
    "pub_date": "2026-11-25 19:35:26",
    "author": "",
    "description": "近日，湖南省永州市冷水滩区各大公园、道路两旁，梧桐次第染金，连片的金色树影绵延铺展，成为一道亮丽的风景线。 近年来，当地践行“生态优先、绿色发展”理念，持续深化城市绿化养护精细化管理，科学配植彩叶树种，打造“四季有景、移步换景”的多彩城市景观，不断擦亮城市生态底色。 制片人：马宝军 策划：李琳 杜屹然 责编：王家辉 编导：邱俊松 报道员：雷中祥 新媒体编辑：杜利伟 供稿来源：冷水滩区融媒体中心 中国新华新闻电视网（CNC）出品",
    "content": "近日，湖南省永州市冷水滩区各大公园、道路两旁，梧桐次第染金，连片的金色树影绵延铺展，成为一道亮丽的风景线。 近年来，当地践行“生态优先、绿色发展”理念，持续深化城市绿化养护精细化管理，科学配植彩叶树种，打造“四季有景、移步换景”的多彩城市景观，不断擦亮城市生态底色。 制片人：马宝军 策划：李琳 杜屹然 责编：王家辉 编导：邱俊松 报道员：雷中祥 新媒体编辑：杜利伟 供稿来源：冷水滩区融媒体中心 中国新华新闻电视网（CNC）出品"
