    "description": "新华社雅加达11月25日电（记者张怡晟）据印度尼西亚搜救部门25日消息，搜救人员当天在该国西爪哇省茂物县一处矿井内发现3名矿工遗体，目前正全力搜救据报仍被困井下的23名矿工。 印尼搜救部门此前通报说，事故发生于23日下午，当时该地区正下大雨，河水泛滥倒灌进矿井。直至25日凌晨，搜救部门才接到人员被困的报告。",
