    "author": "",
    "description": "香港中文大学拟修订大学条例，明确赋予教务会基于刑事定罪、学术不端或行为有损大学声誉等理由，撤销已颁授学位的权力，处分对象包括已毕业的校友。 据香港《星岛日报》上周四（11月19日）报道，四名兼任中大校董的立法会议员提交《香港中文大学条例》修订草案，拟重组教务会，并明确教务会的纪律处分权力。 根据草案，教务会可基于学术不端、伪造学历、违反道德或专业操守、刑事定罪，以及行为有损大学声誉等理由，作出暂停学业、开除学籍或撤销已颁授的学位、文凭及…",
    "content": "香港中文大学拟修订大学条例，明确赋予教务会基于刑事定罪、学术不端或行为有损大学声誉等理由，撤销已颁授学位的权力，处分对象包括已毕业的校友。 据香港《星岛日报》上周四（11月19日）报道，四名兼任中大校董的立法会议员提交《香港中文大学条例》修订草案，拟重组教务会，并明确教务会的纪律处分权力。 根据草案，教务会可基于学术不端、伪造学历、违反道德或专业操守、刑事定罪，以及行为有损大学声誉等理由，作出暂停学业、开除学籍或撤销已颁授的学位、文凭及其他资格等处分。 此次修例也涉及大学整体管治架构，包括调整大学高层任免机制及撤销…"
