    "content": "新华社酒泉11月25日电（记者李国利、刘艺）朝霞铺展，舟启新程。首个中外联合飞行乘组25日驾乘神舟二十四号载人飞船奔赴太空，中国“天宫”首次迎来外籍航天员。 8时18分，我国唯一的载人航天发射场轰鸣骤起，有“神箭”之誉的长征二号F运载火箭点火起飞，托举着神舟飞船腾空而起。 这是中国载人航天工程进入空间站应用与发展阶段的第8次载人飞行任务。中国航天科技集团李文清介绍，相较以前任务，火箭状态稳定，总体方案未发生变化，但型号团队持续攻关，箭上和地面共开展了12项技术改进，以精益求精守护飞天征途。 约10分钟后，神二十四发…"
