    "content": "新华社海口11月25日电（记者何晓）2026中国饭店业高质量大会25日在海南三亚开幕。中国饭店协会相关负责人介绍，当前绿色饭店、康养酒店、非遗美食等新业态、新模式、新场景持续涌现，我国饭店业转型步伐加快。 饭店业是促消费、惠民生、稳就业的重要产业。数据显示，全国住宿业在营设施超59万家，客房总规模突破2000万间；今年1至10月份，全国餐饮收入达4.72万亿元，同比增长2.2%。 中国饭店协会会长陈新华表示，协会将从完善标准体系、打响住宿餐饮消费惠民品牌、发展绿色饭店、推动饭店业数智化升级、培育高技能人才、推动“酒…"
