    "content": "台湾“九合一”地方选举临近，民进党台北市长候选人沈伯洋称，台北与上海举办多年的双城论坛成效有限，并主张台北应考虑与北京举办城市交流论坛。 美国《时代》杂志星期三（11月25日）刊登沈伯洋专访。现年44岁的他将在星期六（28日）举行的地方选举中，挑战寻求连任的国民党籍台北市长蒋万安。 沈伯洋说，台沪双城论坛已举办10多年，但活动往往停留在宣读文件、拍照留念，缺乏实质成效。他以台北具有“首都”地位为由，认为若要举办这类论坛，应考虑直接与北京交流。 但他强调，城市交流必须做好风险管理。他指出，北京对台湾存在武力威胁，若合…"
