    "content": "新华社重庆11月25日电（记者黄兴）重庆市人力社保局、市发展改革委等11部门近日联合印发文件，针对政府项目、国企项目推行人工费单列预算、开工人工费预拨等制度，并在政府项目开展建设单位代发工资试点，从源头保障农民工工资支付。 重庆市人力社保局相关负责人介绍，建设单位代发工资试点指的是，政府项目农民工工资不再经过总包单位、分包单位等中间环节，由建设单位在施工合同签订后1个月内，在项目所在地银行开设农民工工资专用账户，此后每月由建设单位通过该专户将工资直接发放至农民工本人银行卡。 人工费单列管理制度指的是，政府项目、国企…"
